import time
from core.event_bus import EventBus
from core.events import MarketEvent, SignalEvent
from data.mock_adapter import MockDataAdapter
from strategy.sma_crossover import SMACrossoverStrategy

# 1. Setup Bus
bus = EventBus()

# 2. Setup Strategy
strategy = SMACrossoverStrategy(bus)

# 3. Subscribe Strategy to Market Events
bus.subscribe(MarketEvent, strategy.on_market_event)

# 4. Create a handler to listen to the SignalEvents generated by the strategy
def signal_listener(event: SignalEvent):
    print(f"--> [EXECUTION ENGINE RECEIVED] {event.signal_type} signal for {event.symbol} from {event.strategy_id}")

bus.subscribe(SignalEvent, signal_listener)

# 5. Start Feed
adapter = MockDataAdapter(bus)
adapter.start()

# 6. Run for 20 seconds (so we have enough data for crossover)
print("Running Strategy Test for 20 seconds...")
try:
    time.sleep(20)
except KeyboardInterrupt:
    pass
finally:
    adapter.stop()
    print("Test Completed.")
